"""
    Given xs (in pb) and sum of gen weights,
    calculate scale1fb.
    :param xs: cross section (in pb)
    :type xs: float
    :param sum_weights: sum of gen weights
    :type sum_weights: float
    :return: scale1fb
    :rtype: float
    """
def calc_scale1fb(xs: Any, sum_weights: Any) -> object {
    if (xs <= 0) {
        return -1;
    } else {
        return ((xs * 1000.0) / sum_weights);
    }
}

"""Filter out claims/evidence that have zero length.

  Args:
    example: The encoded example
    y_input: Unused, contains the label, included for API compat
  Returns:
    True to preserve example, False to filter it out
  """
def filter_evidence_fn(example: Any, y_input: Any) -> object {
    if ('evidence_text_word_ids' in example) {
        evidence_length = len(example['evidence_text_word_ids']);
    } else {
        evidence_length = len(example['evidence_text']);
    }
    if (evidence_length != 0) {
        return True;
    } else {
        return False;
    }
}

"""
  Replaces multiple slices of text with new values. This is a convenience method for making code
  modifications of ranges e.g. as identified by ``ASTTokens.get_text_range(node)``. Replacements is
  an iterable of ``(start, end, new_text)`` tuples.

  For example, ``replace("this is a test", [(0, 4, "X"), (8, 9, "THE")])`` produces
  ``"X is THE test"``.
  """
def replace(text: Any, replacements: Any) -> object {
    p = 0;
    parts = [];
    for (start, end, new_text) in sorted(replacements) {
        parts.append(text[p:start]);
        parts.append(new_text);
        p = end;
    }
    parts.append(text[p:]);
    return "".join(parts);
}

"""Average for multiple evaluations.

    Args:
        evals [tuple]: several evals without limitation
        ndigits [int]: decimal number of float

    Returns:
        avg [dict]: dict of the average values of all the evaluation metrics
    """
def average_prfacc(*evals: Any, ndigits: Any = 4) -> object {
    avg = {}.fromkeys(evals[0].keys());
    for key in avg {
        values = [e[key] for e in evals];
        if isinstance(values[0], `dict) {
            avg[key] = average_prfacc(*values);
        } else {
            avg[key] = round((sum(values) / len(values)), ndigits);
        }
    }
    return avg;
}

""" Changes Mt. -> Mount
    """
def fix_mounts(report_city: Any) -> object {
    city_components = report_city.split(" ");
    if (city_components[0].strip().lower() == "mt.") {
        city_components[0] = "Mount";
    }
    return " ".join(city_components);
}

